import csv

def parse_amount(text):
    cleaned = text.replace("₹", "").replace(",", "").strip()
    try:
        return float(cleaned)
    except ValueError:
        return None

def parse_rating(text):
    return int(text) if text.strip().isdigit() else None

def load_clean(path):
    rows, seen, dropped = [], set(), 0
    with open(path, newline="", encoding="utf-8") as f:
        for raw in csv.DictReader(f):
            amount = parse_amount(raw["amount"])
            if raw["order_id"] in seen or amount is None:
                dropped += 1
                continue
            seen.add(raw["order_id"])
            rows.append({
                "order_id": raw["order_id"],
                "city": raw["city"].strip().title(),
                "amount": amount,
                "minutes": int(raw["minutes"]),
                "rating": parse_rating(raw["rating"]),
            })
    return rows, dropped

rows, dropped = load_clean("orders.csv")
print(len(rows), "clean rows,", dropped, "dropped")

