def bars(data, width=20):
    if not data:
        return []
    top = max(data.values()) or 1          # avoid dividing by zero
    pad = max(len(label) for label in data)
    lines = []
    for label, value in sorted(data.items(), key=lambda kv: kv[1], reverse=True):
        blocks = "█" * round(value / top * width)
        lines.append(f"{label:<{pad}} {blocks} {value}")
    return lines

for line in bars({"Pune": 1430, "Mumbai": 1820, "Goa": 0}):
    print(line)

